    @service_lookup_handler.implicit_lookup
    def prepare_ues(self, service=None):
        """
        connect to all the ues and get summary information

        :param Optional[Union[str, SparkService]] service: spark service
        :return: summary information of ue
        e.g.
        [
            {'eqindex': 1, 'imsi': 1234567xxxx},
            {'eqindex': 2, 'imsi': abcdeftxxxx},
        ]
        """
        ue_infos = service.prepare_ues()
        return [{'eqindex': ue_info.eqindex, 'imsi': ue_info.imsi} for ue_info in ue_infos]

    @service_lookup_handler.implicit_lookup
    def release_ues(self, service=None):
        """
        disconnect from all the ues and clear summary information

        :param Optional[Union[str, SparkService]] service: spark service
        """
        service.release_ues()

    @service_lookup_handler.implicit_lookup
    def require_ue(self, serial_number=None, imsi=None, service=None, ue_alias=None):
        """
        get a specific ue by the imsi or the first ue

        :param Optional[str] serial_number: default None, if there are more than one Android Ues,
        this field is a must for the adb -s command, when there is only a single Android UE, it is unnecessary
        :param Optional[str] imsi: imsi to specify the ue, if imsi is not set,
        will return the ue with eqindex==1 by default
        :param Optional[Union[str, SparkService]] service: spark service
        :param Optional[str] ue_alias: alias of a UE used in the UE specific keywords

        :return: UE instance
        """
        ue = service.require_ue(serial_number=serial_number, imsi=imsi)
        self.store.add(ue, ue_alias)
        return ue

    @lookup_handler.implicit_lookup
    def release_ue(self, ue=None):
        """
        disconnect from the ue specified and clear its information

        :param Optional[Union[str, UE]] ue: ue under spark service control
        """
        ue.release()

