    @lookup_handler.implicit_lookup
    def is_kirin_chip(self, timeout=None, ue=None):
        """
        check if the ue hardware is kirin serial chips from Huawei

        :param int timeout: command timeout
        :param Optional[Union[str, UE]] ue: ue under spark service control
        :return: True or False
        """
        timeout = int(timeout) if timeout else None
        return ue.adb.is_kirin_chip(timeout=timeout)

    @lookup_handler.implicit_lookup
    def send_adb_command(self, cmd, timeout=None, ue=None):
        """
        send adb command for specific UE

        :param str cmd: adb command string without adb or adb -s
        :param Optional[Union[str, UE]] ue: ue under spark service control

        :return: adb command output
        """
        timeout = int(timeout) if timeout else None
        return ue.adb.execute_command(cmd, timeout=timeout)

    @lookup_handler.implicit_lookup
    def restart_ue_manager(self, ue=None):
        """
        restart the `ue manager` Android app on UE

        :param Optional[Union[str, UE]] ue: ue under spark service control
        """
        ue.adb.restart_ue_manager()

    @lookup_handler.implicit_lookup
    def attach(self, uemode, timeout=None, until_timeout=None, ue=None):
        """
        execute Attach command to attach UE on Qualcomm UE

        :param str uemode: "4G" or "5G_SA" or "5G_NSA"
        :param Optional[int] timeout: timeout(ms) built-in in spark api, 30000 by default
        :param Optional[int] until_timeout: execution timeout in second, 10s by default
        :param Optional[Union[str, UE]] ue: ue under spark service control
        :return: dict
        {
            "CMD": "Attach",
            "EQIndex": 1, # 1 means the first UE,
                          # 2 means the second UE, and so forth.
            "Param": {
                 "State": 0  # return 0 if success, otherwise return the error codes
            }
        }
        """
        until_timeout = int(until_timeout) if until_timeout else None
        timeout = int(timeout) if timeout else 30000
        return ue.attach(uemode, timeout=timeout, until_timeout=until_timeout).dictionary

