    @lookup_handler.implicit_lookup
    def startultraffic(self, protocol, address, port, testtime, bandwidth, buffersize, packetsize,
                       until_timeout=None, ue=None):
        """
        execute StartULtraffic to start Up Link Traffic

        :param str protocol: traffic protocol, e.g. 'UDP', 'TCP', 'UDP' by default
        :param str address: target(e.g. app server) ip address
        :param int port: target port NO.
        :param int testtime: time last for traffic in seconds
        :param int bandwidth: bandwidth in Kbps
        :param int buffersize: buffersize in KB
        :param int packetsize: packetsize in Byte
        :param Optional[int] until_timeout: execution timeout in second, 10s by default
        :param Optional[Union[str, UE]] ue: ue under spark service control
        :return: dict
        {
            "CMD": "StartULtraffic",
            "EQIndex": 1, # {-1, 1~n}, -1 means all UEs, 1 means the first UE,
                          # 2 means the second UE, and so forth.
            "Param": {
                 "State": 0  # return 0 if success, otherwise return the error codes
            }
        }
        """
        until_timeout = int(until_timeout) if until_timeout else None
        port = int(port)
        testtime = int(testtime)
        bandwidth = int(bandwidth)
        buffersize = int(buffersize)
        packetsize = int(packetsize)
        return ue.startultraffic(protocol, address, port, testtime, bandwidth, buffersize, packetsize,
                                 until_timeout=until_timeout).dictionary

