    @lookup_handler.implicit_lookup
    def getparamvalue(self, parameters=None, until_timeout=None, ue=None):
        """
        execute getparamvalue command to get parameter(s)' value

        :param Optional[List[str]] parameters: 5GNR parameters, must be in a NR5G Parameter list as the following:
            NR SSB ARFCN DL,NR PCI,NR SSB RSRP[dBm],NR SSB SINR[dB],NR SSB RSRQ[dB],NR SSB RSSI[dBm],
            NR SDAP Thr. DL [Mbps],NR PDCP Thr. DL [Mbps],NR RLC Thr. DL [Mbps],NR MAC Thr. DL [Mbps],
            NR PHY Thr. DL [Mbps],NR SDAP Thr. UL [Mbps],NR PDCP Thr. UL [Mbps],NR RLC Thr. UL [Mbps],
            NR MAC Thr. UL [Mbps],NR PHY Thr. UL [Mbps],NR PDSCH TotalRBCount,NR PDSCH SlotCount,
            NR PDSCH RBCountPerSlot,NR PUSCH TotalRBCount,NR PUSCH SlotCount,NR PUSCH RBCountPerSlot,
            NR PDCCH DL Grant Count,NR PDCCH UL Grant Count,NR PDSCH BLER[%],NR PDSCH iBLER[%],
            NR PDSCH Resi.BLER[%],NR PUSCH BLER[%],NR PUSCH iBLER[%],NR PUSCH Resi.BLER[%],NR PDCCH BLER[%],
            NR Rank Avg. DL,NR Rank Avg. UL,NR MCS Avg. DL,NR MCS Avg. UL,NR Modulation Most DL,NR Modulation Most UL,
            NR CQI Avg.,NR MCC,NR MNC,NR Band,NR BandWidth DL,NR WorkMode DL,NR Cell ID,NR gNodeB ID,NR Sector ID,
            NR SubCarrierSpace,NR SS GSCN,NR SSB Freq. DL(MHz),NR PointA ARFCN DL,NR PointA Freq. DL(MHz),
            NR Center ARFCN DL,NR Center Freq. DL(MHz),NR PDSCH DMRS PortIndex,NR PDSCH DMRS LayerIndex,
            NR PDSCH DMRS RSSI[dBm],NR PDSCH DMRS SINR[dB],NR PUCCH DMRS PortIndex,NR PUCCH DMRS LayerIndex,
            NR PUCCH DMRS RSSI[dBm],NR PUCCH DMRS SINR[dB],NR PDSCH TBS Avg.,NR PUSCH TBS Avg.,NR RACH Preamble ID,
            NR PUSCH TxPower,NR PUCCH TxPower,NR PRACH TxPower,NR PathLoss,RRC Status,Current Network, Longitude,
            Latitude,Product Version
            all by default
        :param Optional[int] until_timeout: execution timeout in second, 10s by default
        :param Optional[Union[str, UE]] ue: ue under spark service control
        :return: dict
        e.g.
        {"CMD": "GetParamValue",
         "EQIndex": 1,
         "Param": {"State": 0,
                   "Values": ["-88.68", "10.61", "295" ]
                  }
        }
        """

        until_timeout = int(until_timeout) if until_timeout else None
        return ue.getparamvalue(parameters=parameters, until_timeout=until_timeout).dictionary
